func:
// 模擬設備：数秒ごとに状態を変えて MQTT に出す。
// 実機では、このノードの代わりに PLC から状態を読むノード（OPC UA・MC プロトコル・Modbus など）を置き、
// 同じ形（state・alarmCode・occurredAt）で同じトピックへ出せばよい
const states = ['Running', 'Running', 'Running', 'Idle', 'Setup', 'Stopped', 'Failure'];
const alarms = { Stopped: ['A-101', 'A-102', 'Z-999'], Failure: ['E-201'] };
const state = states[Math.floor(Math.random() * states.length)];
const codes = alarms[state];
msg.topic = 'mes/equipment/' + (env.get('SIM_EQUIPMENT') || 'EQ-06') + '/state';
msg.payload = {
    state: state,
    alarmCode: codes ? codes[Math.floor(Math.random() * codes.length)] : null,
    occurredAt: new Date().toISOString()
};
node.status({ text: state });
return msg;

// トピック mes/equipment/<資産番号>/state から設備を、本文から状態を取り出して送信待ちにためる。
// eventId はここで振る（送り直しても同じ値のままなので、MES 側で重複として弾かれる）
const code = msg.topic.split('/')[2];
const p = msg.payload || {};
const seq = (flow.get('seq') || 0) + 1;
flow.set('seq', seq);
const queue = flow.get('queue') || [];
queue.push({
    equipmentCode: code,
    eventId: code + '-' + Date.now() + '-' + seq,
    occurredAt: p.occurredAt || new Date().toISOString(),
    state: p.state,
    alarmCode: p.alarmCode || null
});
// MES に届かない間もためておく。ため過ぎないよう、上限を超えたら古いものから捨てる
const limit = 10000;
flow.set('queue', queue.length > limit ? queue.slice(queue.length - limit) : queue);
node.status({ text: '送信待ち ' + Math.min(queue.length, limit) + ' 件' });
return null;

// ためたイベントをまとめて MES へ送る。前の送信の結果が返るまでは次を送らない
if (flow.get('sending')) {
    return null;
}
const queue = flow.get('queue') || [];
if (queue.length === 0) {
    return null;
}
const batch = queue.slice(0, 500);
flow.set('sending', batch.length);
msg.url = (env.get('MES_URL') || 'http://mesapp:8080') + '/api/integration/v1/equipment-events';
msg.method = 'POST';
msg.headers = { 'X-Api-Key': env.get('MES_API_KEY') || '', 'Content-Type': 'application/json' };
msg.payload = { events: batch };
return msg;

// 送った分を送信待ちから外す。送れなかったとき（MES が止まっている・キーが違う）は外さず、次の回に送り直す。
// 1件ごとの拒否（遅着・設定の誤りなど）は送り直しても通らないので、デバッグ欄に出すだけにする
const sent = flow.get('sending') || 0;
flow.set('sending', 0);
if (msg.statusCode === 400) {
    // 要求の形が壊れている（送り直しても通らない）。送信待ちから外して知らせる
    flow.set('queue', (flow.get('queue') || []).slice(sent));
    node.status({ fill: 'red', shape: 'dot', text: '要求が拒否されました（400）' });
    node.warn(msg.payload);
    return null;
}
if (msg.statusCode === undefined) {
    // MES に繋がらなかった（名前が引けない・接続を拒否された等）。HTTP ノードはエラーをここにも流す
    node.status({ fill: 'yellow', shape: 'ring', text: '繋がりません。次の回に送り直します' });
    return null;
}
if (msg.statusCode !== 200) {
    node.status({ fill: 'yellow', shape: 'ring', text: '送れませんでした（' + msg.statusCode + '）。次の回に送り直します' });
    node.warn(msg.payload);
    return null;
}
flow.set('queue', (flow.get('queue') || []).slice(sent));
const r = msg.payload;
node.status({ fill: 'green', shape: 'dot', text: '採用 ' + r.accepted + '・重複 ' + r.duplicate + '・拒否 ' + r.rejected });
const rejected = r.results.filter(x => x.result === 'Rejected');
if (rejected.length === 0) {
    return null;
}
msg.payload = rejected;
return msg;

// MES に繋がらなかった（名前が引けない・接続を拒否された等）。送信待ちは残し、次の回に送り直す
flow.set('sending', 0);
node.status({ fill: 'yellow', shape: 'ring', text: '繋がりません。次の回に送り直します' });
return null;
